    #[must_use]
    pub fn credential_class_policies(&self) -> ActingCredentialClassPolicyRepo<'a> {
        ActingCredentialClassPolicyRepo {
            store: self.store,
            scope: self.scope,
            acting: self.acting,
        }
    }

    /// The mutating attestation-config repository for this scope and actor (issue #66):
