    /// bookkeeping are off the audited path (exactly like the abuse counters).
    #[must_use]
    pub fn sms_otp(&self) -> ActingSmsOtpRepo<'a> {
        ActingSmsOtpRepo {
            store: self.store,
            scope: self.scope,
            acting: self.acting,
        }
    }

    /// The impersonation-authorization repository for this scope and actor (issue #101).
